import numpy as np

def kernel(x, eps=1e-6):
    M, N = x.shape
    y = np.zeros_like(x, dtype=np.float32)
    tile_rows = 128
    tile_cols = 512

    # Compute row-wise RMS over the entire row
    row_rms = np.zeros(M, dtype=np.float32)
    for i in range(M):
        row = x[i, :]
        row_rms[i] = np.sqrt(np.mean(row ** 2) + eps)

    # Normalize tile by tile using the precomputed row_rms
    for i in range(0, M, tile_rows):
        for j in range(0, N, tile_cols):
            end_row = min(i + tile_rows, M)
            end_col = min(j + tile_cols, N)
            for r in range(i, end_row):
                for c in range(j, end_col):
                    y[r, c] = x[r, c] / row_rms[r]

    return y

